     1→// FreeLang v6: Bytecode Compiler
     2→
     3→import { Expr, Stmt, Program, MatchArm } from "./ast";
     4→
     5→export enum Op {
     6→  Const, Pop, Dup,
     7→  Add, Sub, Mul, Div, Mod, Neg,
     8→  Eq, Neq, Lt, Gt, Lte, Gte,
     9→  And, Or, Not,
    10→  Jump, JumpIfFalse, JumpIfTrue,
    11→  Load, Store, LoadGlobal, StoreGlobal,
    12→  Call, Return, Builtin,
    13→  NewArray, Index, SetIndex,
    14→  NewObject, GetProp, SetProp,
    15→  NewClosure, LoadFree, StoreFree,
    16→  Print, Println,
    17→  TryBegin, TryEnd, Throw,
    18→  Iter, IterNext, IterDone,
    19→  AddrOf, Deref,  // v5.9.1: Pointer operators
    20→  Halt,
    21→}
    22→
    23→export type Value =
    24→  | { tag: "num"; val: number }
    25→  | { tag: "str"; val: string }
    26→  | { tag: "bool"; val: boolean }
    27→  | { tag: "null" }
    28→  | { tag: "array"; val: Value[] }
    29→  | { tag: "object"; val: Map<string, Value> }
    30→  | { tag: "fn"; name: string; arity: number; addr: number; freeVars: Value[] }
    31→  | { tag: "builtin"; name: string }
    32→  | { tag: "iter"; val: Value[]; idx: number }
    33→  | { tag: "ptr"; addr: number; target: Value }; // Pointer type (v5.9.1)
    34→
    35→export type Chunk = {
    36→  code: number[];
    37→  constants: Value[];
    38→  lines: number[];
    39→};
    40→
    41→type Local = { name: string; depth: number };
    42→type Upvalue = { name: string; isLocal: boolean; index: number };
    43→type CompilerScope = {
    44→  locals: Local[];
    45→  depth: number;
    46→  upvalues: Upvalue[];
    47→};
    48→
    49→type LoopInfo = { startAddr: number; breakPatches: number[] };
    50→
    51→export function compile(program: Program): Chunk {
    52→  const chunk: Chunk = { code: [], constants: [], lines: [] };
    53→  const scopes: CompilerScope[] = [{ locals: [], depth: 0, upvalues: [] }];
    54→  const globals = new Set<string>();
    55→  const loopStack: LoopInfo[] = [];
    56→  const finallyStack: Stmt[][] = [];
    57→
    58→  function emit(op: Op, line = 0) { chunk.code.push(op); chunk.lines.push(line); }
    59→  function emitArg(op: Op, arg: number, line = 0) { emit(op, line); chunk.code.push(arg); chunk.lines.push(line); }
    60→  function addConst(val: Value): number {
    61→    chunk.constants.push(val);
    62→    return chunk.constants.length - 1;
    63→  }
    64→  function currentPos(): number { return chunk.code.length; }
    65→  function patchJump(pos: number) { chunk.code[pos + 1] = currentPos(); }
    66→
    67→  function scope(): CompilerScope { return scopes[scopes.length - 1]; }
    68→
    69→  function resolveLocal(name: string): number {
    70→    const locals = scope().locals;
    71→    for (let i = locals.length - 1; i >= 0; i--) {
    72→      if (locals[i].name === name) return i;
    73→    }
    74→    return -1;
    75→  }
    76→
    77→  function declareLocal(name: string) {
    78→    scope().locals.push({ name, depth: scope().depth });
    79→  }
    80→
    81→  function resolveUpvalue(name: string): number {
    82→    if (scopes.length < 2) return -1;
    83→    const s = scope();
    84→    for (let i = 0; i < s.upvalues.length; i++) {
    85→      if (s.upvalues[i].name === name) return i;
    86→    }
    87→    const parent = scopes[scopes.length - 2];
    88→    for (let j = parent.locals.length - 1; j >= 0; j--) {
    89→      if (parent.locals[j].name === name) {
    90→        s.upvalues.push({ name, isLocal: true, index: j });
    91→        return s.upvalues.length - 1;
    92→      }
    93→    }
    94→    for (let j = 0; j < parent.upvalues.length; j++) {
    95→      if (parent.upvalues[j].name === name) {
    96→        s.upvalues.push({ name, isLocal: false, index: j });
    97→        return s.upvalues.length - 1;
    98→      }
    99→    }
   100→    return -1;
   101→  }
   102→
   103→  function compileStmts(stmts: Stmt[]) {
   104→    for (const s of stmts) compileStmt(s);
   105→  }
   106→
   107→  // Compile statements where the last expr must leave a value on the stack
   108→  function compileStmtsAsExpr(stmts: Stmt[]) {
   109→    for (let i = 0; i < stmts.length; i++) {
   110→      const s = stmts[i];
   111→      const isLast = i === stmts.length - 1;
   112→
   113→      if (isLast && s.kind === "expr") {
   114→        // Last statement is an expression: compile it but DON'T pop
   115→        compileExpr(s.expr);
   116→      } else if (isLast && s.kind === "if") {
   117→        // Last statement is an if-statement in expression context
   118→        // Both branches must leave values on the stack
   119→        compileExpr(s.cond);
   120→        const jumpFalse = currentPos(); emitArg(Op.JumpIfFalse, 0);
   121→        compileStmtsAsExpr(s.then);
   122→        if (s.else) {
   123→          const jumpEnd = currentPos(); emitArg(Op.Jump, 0);
   124→          patchJump(jumpFalse);
   125→          compileStmtsAsExpr(s.else);
   126→          patchJump(jumpEnd);
   127→        } else {
   128→          // If-statement without else in expression context: push null as default
   129→          emitArg(Op.Const, addConst({ tag: "null" }));
   130→          const jumpEnd = currentPos(); emitArg(Op.Jump, 0);
   131→          patchJump(jumpFalse);
   132→          patchJump(jumpEnd);
   133→        }
   134→      } else {
   135→        compileStmt(s);
   136→      }
   137→    }
   138→  }
   139→
   140→  function compileStmt(s: Stmt) {
   141→    switch (s.kind) {
   142→      case "expr": compileExpr(s.expr); emit(Op.Pop); break;
   143→      case "let": {
   144→        if (scope().depth === 0) {
   145→          globals.add(s.name);
   146→          if (s.init) compileExpr(s.init); else emitArg(Op.Const, addConst({ tag: "null" }));
   147→          emitArg(Op.StoreGlobal, addConst({ tag: "str", val: s.name }));
   148→        } else {
   149→          declareLocal(s.name);
   150→          if (s.init) compileExpr(s.init); else emitArg(Op.Const, addConst({ tag: "null" }));
   151→          // Store the value in the local variable slot
   152→          emitArg(Op.Store, scope().locals.length - 1);
   153→        }
   154→        break;
   155→      }
   156→      case "fn": {
   157→        if (scope().depth === 0) globals.add(s.name);
   158→        else declareLocal(s.name);
   159→        compileFnBody(s.name, s.params, s.body);
   160→        if (scope().depth === 0) {
   161→          emitArg(Op.StoreGlobal, addConst({ tag: "str", val: s.name }));
   162→        }
   163→        break;
   164→      }
   165→      case "return": {
   166→        // Emit any pending finally blocks first
   167→        for (const fb of [...finallyStack].reverse()) {
   168→          compileStmts(fb);
   169→        }
   170→        if (s.value) compileExpr(s.value); else emitArg(Op.Const, addConst({ tag: "null" }));
   171→        emit(Op.Return);
   172→        break;
   173→      }
   174→      case "if": {
   175→        compileExpr(s.cond);
   176→        const jumpFalse = currentPos(); emitArg(Op.JumpIfFalse, 0);
   177→        compileStmts(s.then);
   178→        if (s.else) {
   179→          const jumpEnd = currentPos(); emitArg(Op.Jump, 0);
   180→          patchJump(jumpFalse);
   181→          compileStmts(s.else);
   182→          patchJump(jumpEnd);
   183→        } else {
   184→          patchJump(jumpFalse);
   185→        }
   186→        break;
   187→      }
   188→      case "while": {
   189→        const loop: LoopInfo = { startAddr: currentPos(), breakPatches: [] };
   190→        loopStack.push(loop);
   191→        compileExpr(s.cond);
   192→        const exit = currentPos(); emitArg(Op.JumpIfFalse, 0);
   193→        compileStmts(s.body);
   194→        emitArg(Op.Jump, loop.startAddr);
   195→        patchJump(exit);
   196→        for (const bp of loop.breakPatches) patchJump(bp);
   197→        loopStack.pop();
   198→        break;
   199→      }
   200→      case "for": {
   201→        // Compile iterator expression, store as global __iter_N
   202→        compileExpr(s.iter);
   203→        emit(Op.Iter);
   204→        const iterName = `__iter_${currentPos()}`;
   205→        emitArg(Op.StoreGlobal, addConst({ tag: "str", val: iterName }));
   206→        const loop: LoopInfo = { startAddr: currentPos(), breakPatches: [] };
   207→        loopStack.push(loop);
   208→        // Check done
   209→        emitArg(Op.LoadGlobal, addConst({ tag: "str", val: iterName }));
   210→        emit(Op.IterDone);
   211→        const exit = currentPos(); emitArg(Op.JumpIfTrue, 0);
   212→        // Get next value, store as loop variable
   213→        emitArg(Op.LoadGlobal, addConst({ tag: "str", val: iterName }));
   214→        emit(Op.IterNext);
   215→        emitArg(Op.StoreGlobal, addConst({ tag: "str", val: s.name }));
   216→        compileStmts(s.body);
   217→        emitArg(Op.Jump, loop.startAddr);
   218→        patchJump(exit);
   219→        for (const bp of loop.breakPatches) patchJump(bp);
   220→        loopStack.pop();
   221→        break;
   222→      }
   223→      case "block": {
   224→        scope().depth++;
   225→        compileStmts(s.body);
   226→        const localsToRemove = scope().locals.filter(l => l.depth === scope().depth).length;
   227→        for (let i = 0; i < localsToRemove; i++) { emit(Op.Pop); scope().locals.pop(); }
   228→        scope().depth--;
   229→        break;
   230→      }
   231→      case "break": {
   232→        if (loopStack.length === 0) throw new Error("break outside loop");
   233→        const bp = currentPos(); emitArg(Op.Jump, 0);
   234→        loopStack[loopStack.length - 1].breakPatches.push(bp);
   235→        break;
   236→      }
   237→      case "continue": {
   238→        if (loopStack.length === 0) throw new Error("continue outside loop");
   239→        emitArg(Op.Jump, loopStack[loopStack.length - 1].startAddr);
   240→        break;
   241→      }
   242→      case "print": {
   243→        compileExpr(s.expr);
   244→        emit(s.newline ? Op.Println : Op.Print);
   245→        break;
   246→      }
   247→      case "try": {
   248→        // Push finally block to stack if present
   249→        if (s.finallyBody.length > 0) {
   250→          finallyStack.push(s.finallyBody);
   251→        }
   252→
   253→        const tryBegin = currentPos(); emitArg(Op.TryBegin, 0); // catch addr
   254→        compileStmts(s.body);  // return inside here will see finallyStack
   255→        emit(Op.TryEnd);
   256→
   257→        // Pop finally block from stack after compiling try body
   258→        if (s.finallyBody.length > 0) {
   259→          finallyStack.pop();
   260→        }
   261→
   262→        const jumpFinally = currentPos(); emitArg(Op.Jump, 0);
   263→        // Catch
   264→        patchJump(tryBegin);
   265→        if (s.catchVar) {
   266→          scope().depth++;
   267→          declareLocal(s.catchVar);
   268→          compileStmts(s.catchBody);
   269→          const localsToRemove = scope().locals.filter(l => l.depth === scope().depth).length;
   270→          for (let i = 0; i < localsToRemove; i++) { emit(Op.Pop); scope().locals.pop(); }
   271→          scope().depth--;
   272→        } else {
   273→          emit(Op.Pop); // discard error
   274→          compileStmts(s.catchBody);
   275→        }
   276→        // Finally
   277→        patchJump(jumpFinally);
   278→        compileStmts(s.finallyBody);
   279→        break;
   280→      }
   281→      case "throw": {
   282→        compileExpr(s.expr);
   283→        emit(Op.Throw);
   284→        break;
   285→      }
   286→      case "struct": {
   287→        // Store struct definition as global with type metadata
   288→        globals.add(s.name);
   289→
   290→        // Create struct object with field information
   291→        const structVal = new Map<string, Value>();
   292→
   293→        // Add each field with null default
   294→        for (const field of s.fields) {
   295→          structVal.set(field.name, { tag: "null" });
   296→        }
   297→
   298→        // Store field metadata as JSON
   299→        const fieldMetadata = s.fields.map(f => ({ name: f.name, type: f.type }));
   300→        structVal.set("__fields__", { tag: "str", val: JSON.stringify(fieldMetadata) });
   301→        structVal.set("__struct_name__", { tag: "str", val: s.name });
   302→
   303→        emitArg(Op.Const, addConst({ tag: "object", val: structVal }));
   304→        emitArg(Op.StoreGlobal, addConst({ tag: "str", val: s.name }));
   305→        break;
   306→      }
   307→      case "import": break; // handled by module loader
   308→      case "export": compileStmt(s.stmt); break; // compile inner stmt
   309→      case "multi": compileStmts(s.stmts); break;
   310→      case "match": {
   311→        // Compile subject once, store as temp global
   312→        compileExpr(s.subject);
   313→        const tempName = `__match_${currentPos()}`;
   314→        emitArg(Op.StoreGlobal, addConst({ tag: "str", val: tempName }));
   315→        const endPatches: number[] = [];
   316→        for (const arm of s.arms) {
   317→          if (arm.pattern !== null) {
   318→            emitArg(Op.LoadGlobal, addConst({ tag: "str", val: tempName }));
   319→            compileExpr(arm.pattern);
   320→            emit(Op.Eq);
   321→            const skip = currentPos(); emitArg(Op.JumpIfFalse, 0);
   322→            compileStmts(arm.body);
   323→            endPatches.push(currentPos()); emitArg(Op.Jump, 0);
   324→            patchJump(skip);
   325→          } else {
   326→            // Default arm (_)
   327→            compileStmts(arm.body);
   328→          }
   329→        }
   330→        const end = currentPos();
   331→        for (const p of endPatches) patchJump(p);
   332→        break;
   333→      }
   334→      case "if-let": {
   335→        // If let: pattern matching with optional else
   336→        compileExpr(s.value);
   337→        const tempName = `__iflet_${currentPos()}`;
   338→        emitArg(Op.StoreGlobal, addConst({ tag: "str", val: tempName }));
   339→
   340→        // Compare value with pattern
   341→        emitArg(Op.LoadGlobal, addConst({ tag: "str", val: tempName }));
   342→        compileExpr(s.pattern);
   343→        emit(Op.Eq);
   344→
   345→        const skipBody = currentPos();
   346→        emitArg(Op.JumpIfFalse, 0);
   347→
   348→        // Execute body
   349→        compileStmts(s.body);
   350→
   351→        const skipElse = currentPos();
   352→        emitArg(Op.Jump, 0);
   353→
   354→        // Execute else (if exists)
   355→        patchJump(skipBody);
   356→        if (s.else) {
   357→          compileStmts(s.else);
   358→        }
   359→
   360→        patchJump(skipElse);
   361→        break;
   362→      }
   363→      case "while-let": {
   364→        // While let: repeat while pattern matches
   365→        const loopStart = currentPos();
   366→
   367→        // Evaluate value
   368→        compileExpr(s.value);
   369→        const tempName = `__whilelet_${currentPos()}`;
   370→        emitArg(Op.StoreGlobal, addConst({ tag: "str", val: tempName }));
   371→
   372→        // Try to match pattern
   373→        emitArg(Op.LoadGlobal, addConst({ tag: "str", val: tempName }));
   374→        compileExpr(s.pattern);
   375→        emit(Op.Eq);
   376→
   377→        const exit = currentPos();
   378→        emitArg(Op.JumpIfFalse, 0);
   379→
   380→        // Execute body
   381→        compileStmts(s.body);
   382→
   383→        // Loop back
   384→        emitArg(Op.Jump, loopStart);
   385→
   386→        patchJump(exit);
   387→        break;
   388→      }
   389→    }
   390→  }
   391→
   392→  function compileFnBody(name: string, params: string[], body: Stmt[]) {
   393→    const jumpOver = currentPos(); emitArg(Op.Jump, 0);
   394→    const fnAddr = currentPos();
   395→    scopes.push({ locals: [], depth: 1, upvalues: [] });
   396→    for (const p of params) declareLocal(p);
   397→    // Compile body as expression: last stmt should leave value on stack
   398→    if (body.length === 0) {
   399→      emitArg(Op.Const, addConst({ tag: "null" }));
   400→    } else {
   401→      compileStmtsAsExpr(body);
   402→    }
   403→    emit(Op.Return);
   404→    const fnScope = scopes.pop()!;
   405→    patchJump(jumpOver);
   406→
   407→    if (fnScope.upvalues.length > 0) {
   408→      for (const uv of fnScope.upvalues) {
   409→        if (uv.isLocal) emitArg(Op.Load, uv.index);
   410→        else emitArg(Op.LoadFree, uv.index);
   411→      }
   412→      emitArg(Op.Const, addConst({ tag: "fn", name, arity: params.length, addr: fnAddr, freeVars: [] }));
   413→      emitArg(Op.NewClosure, fnScope.upvalues.length);
   414→    } else {
   415→      emitArg(Op.Const, addConst({ tag: "fn", name, arity: params.length, addr: fnAddr, freeVars: [] }));
   416→    }
   417→  }
   418→
   419→  function compileExpr(e: Expr) {
   420→    switch (e.kind) {
   421→      case "number": emitArg(Op.Const, addConst({ tag: "num", val: e.value })); break;
   422→      case "string": emitArg(Op.Const, addConst({ tag: "str", val: e.value })); break;
   423→      case "bool": emitArg(Op.Const, addConst({ tag: "bool", val: e.value })); break;
   424→      case "null": emitArg(Op.Const, addConst({ tag: "null" })); break;
   425→      case "ident": {
   426→        const local = resolveLocal(e.name);
   427→        if (local !== -1) { emitArg(Op.Load, local); break; }
   428→        const upval = resolveUpvalue(e.name);
   429→        if (upval !== -1) { emitArg(Op.LoadFree, upval); break; }
   430→        emitArg(Op.LoadGlobal, addConst({ tag: "str", val: e.name }));
   431→        break;
   432→      }
   433→      case "binary": {
   434→        compileExpr(e.left);
   435→        compileExpr(e.right);
   436→        const ops: Record<string, Op> = {
   437→          "+": Op.Add, "-": Op.Sub, "*": Op.Mul, "/": Op.Div, "%": Op.Mod,
   438→          "==": Op.Eq, "!=": Op.Neq, "<": Op.Lt, ">": Op.Gt, "<=": Op.Lte, ">=": Op.Gte,
   439→          "&&": Op.And, "||": Op.Or,
   440→        };
   441→        emit(ops[e.op]);
   442→        break;
   443→      }
   444→      case "unary": {
   445→        compileExpr(e.expr);
   446→        if (e.op === "-") emit(Op.Neg);
   447→        else if (e.op === "!" || e.op === "not") emit(Op.Not);
   448→        else if (e.op === "&") emit(Op.AddrOf);  // v5.9.1: Address-of operator
   449→        else if (e.op === "*") emit(Op.Deref);   // v5.9.1: Dereference operator
   450→        break;
   451→      }
   452→      case "call": {
   453→        compileExpr(e.callee); // Standard ident resolution: local → upvalue → global
   454→        for (const arg of e.args) compileExpr(arg);
   455→        emitArg(Op.Call, e.args.length);
   456→        break;
   457→      }
   458→      case "assign": {
   459→        compileExpr(e.value);
   460→        if (e.target.kind === "ident") {
   461→          const local = resolveLocal(e.target.name);
   462→          if (local !== -1) { emit(Op.Dup); emitArg(Op.Store, local); }
   463→          else {
   464→            const upval = resolveUpvalue(e.target.name);
   465→            if (upval !== -1) { emit(Op.Dup); emitArg(Op.StoreFree, upval); }
   466→            else { emit(Op.Dup); emitArg(Op.StoreGlobal, addConst({ tag: "str", val: e.target.name })); }
   467→          }
   468→        } else if (e.target.kind === "index") {
   469→          compileExpr(e.target.object);
   470→          compileExpr(e.target.index);
   471→          emit(Op.SetIndex);
   472→        } else if (e.target.kind === "member") {
   473→          compileExpr(e.target.object);
   474→          emitArg(Op.Const, addConst({ tag: "str", val: e.target.property }));
   475→          emit(Op.SetProp);
   476→        }
   477→        break;
   478→      }
   479→      case "array": {
   480→        for (const el of e.elements) compileExpr(el);
   481→        emitArg(Op.NewArray, e.elements.length);
   482→        break;
   483→      }
   484→      case "object": {
   485→        for (const { key, value } of e.entries) {
   486→          emitArg(Op.Const, addConst({ tag: "str", val: key }));
   487→          compileExpr(value);
   488→        }
   489→        emitArg(Op.NewObject, e.entries.length);
   490→        break;
   491→      }
   492→      case "index": {
   493→        compileExpr(e.object);
   494→        compileExpr(e.index);
   495→        emit(Op.Index);
   496→        break;
   497→      }
   498→      case "member": {
   499→        compileExpr(e.object);
   500→        emitArg(Op.GetProp, addConst({ tag: "str", val: e.property }));
   501→        break;
   502→      }
   503→      case "fn": {
   504→        compileFnBody(e.name ?? "<anon>", e.params, e.body);
   505→        break;
   506→      }
   507→      case "ternary": {
   508→        compileExpr(e.cond);
   509→        const jumpFalse = currentPos(); emitArg(Op.JumpIfFalse, 0);
   510→        compileExpr(e.then);
   511→        const jumpEnd = currentPos(); emitArg(Op.Jump, 0);
   512→        patchJump(jumpFalse);
   513→        compileExpr(e.else);
   514→        patchJump(jumpEnd);
   515→        break;
   516→      }
   517→      case "if": {
   518→        // If-expression: if cond { then_block } else { else_block }
   519→        // Both blocks must produce a value on the stack (don't pop last expr)
   520→        compileExpr(e.cond);
   521→        const jumpFalse = currentPos(); emitArg(Op.JumpIfFalse, 0);
   522→        compileStmtsAsExpr(e.then);
   523→        const jumpEnd = currentPos(); emitArg(Op.Jump, 0);
   524→        patchJump(jumpFalse);
   525→        compileStmtsAsExpr(e.else);
   526→        patchJump(jumpEnd);
   527→        break;
   528→      }
   529→      case "match": {
   530→        // Match expression: evaluate subject and match against patterns
   531→        compileExpr(e.subject);
   532→        const tempName = `__match_${currentPos()}`;
   533→        emitArg(Op.StoreGlobal, addConst({ tag: "str", val: tempName }));
   534→
   535→        const endPatches: number[] = [];
   536→        for (const arm of e.arms) {
   537→          if (arm.pattern !== null) {
   538→            // Load subject for comparison
   539→            emitArg(Op.LoadGlobal, addConst({ tag: "str", val: tempName }));
   540→
   541→            // Compile pattern and compare
   542→            compileExpr(arm.pattern);
   543→            emit(Op.Eq);
   544→
   545→            // If guard exists, add it to the condition with AND
   546→            if (arm.guard) {
   547→              compileExpr(arm.guard);
   548→              emit(Op.And);
   549→            }
   550→
   551→            const skip = currentPos();
   552→            emitArg(Op.JumpIfFalse, 0);
   553→
   554→            // Compile body as expression (preserve last value)
   555→            compileStmtsAsExpr(arm.body);
   556→
   557→            endPatches.push(currentPos());
   558→            emitArg(Op.Jump, 0);
   559→            patchJump(skip);
   560→          } else {
   561→            // Wildcard/default arm - always matches
   562→            if (arm.guard) {
   563→              // Even wildcard can have guard
   564→              compileExpr(arm.guard);
   565→              const skip = currentPos();
   566→              emitArg(Op.JumpIfFalse, 0);
   567→              compileStmtsAsExpr(arm.body);
   568→              endPatches.push(currentPos());
   569→              emitArg(Op.Jump, 0);
   570→              patchJump(skip);
   571→            } else {
   572→              // Default case - execute unconditionally
   573→              compileStmtsAsExpr(arm.body);
   574→            }
   575→          }
   576→        }
   577→
   578→        // Patch all end jumps
   579→        const end = currentPos();
   580→        for (const p of endPatches) patchJump(p);
   581→        break;
   582→      }
   583→    }
   584→  }
   585→
   586→  compileStmts(program.stmts);
   587→  emit(Op.Halt);
   588→  return chunk;
   589→}
   590→

