   446→  // --- Expressions (Pratt) ---
   447→  function parseExpr(): Expr { return parseAssign(); }
   448→
   449→  function parseAssign(): Expr {
   450→    let left = parseOr();
   451→    if (at(T.Assign) || at(T.PlusAssign) || at(T.MinusAssign) || at(T.StarAssign) || at(T.SlashAssign)) {
   452→      const op = advance();
   453→      const right = parseAssign();
   454→      if (op.type === T.Assign) return { kind: "assign", target: left, value: right };
   455→      const binOp = op.value[0]; // +, -, *, /
   456→      return { kind: "assign", target: left, value: { kind: "binary", op: binOp, left, right } };
   457→    }
   458→    return left;
   459→  }
   460→
   461→  function parseOr(): Expr {
   462→    let left = parseAnd();
   463→    while (match(T.Or)) left = { kind: "binary", op: "||", left, right: parseAnd() };
   464→    return left;
   465→  }
   466→
   467→  function parseAnd(): Expr {
   468→    let left = parseEquality();
   469→    while (match(T.And)) left = { kind: "binary", op: "&&", left, right: parseEquality() };
   470→    return left;
   471→  }
   472→
   473→  function parseEquality(): Expr {
   474→    let left = parseComparison();
   475→    while (at(T.Eq) || at(T.Neq)) {
   476→      const op = advance().value;
   477→      left = { kind: "binary", op, left, right: parseComparison() };
   478→    }
   479→    return left;
   480→  }
   481→
   482→  function parseComparison(): Expr {
   483→    let left = parseAddition();
   484→    while (at(T.Lt) || at(T.Gt) || at(T.Lte) || at(T.Gte)) {
   485→      const op = advance().value;
   486→      left = { kind: "binary", op, left, right: parseAddition() };
   487→    }
   488→    return left;
   489→  }
   490→
   491→  function parseAddition(): Expr {
   492→    let left = parseMultiplication();
   493→    while (at(T.Plus) || at(T.Minus)) {
   494→      const op = advance().value;
   495→      left = { kind: "binary", op, left, right: parseMultiplication() };
   496→    }
   497→    return left;
   498→  }
   499→
   500→  function parseMultiplication(): Expr {
   501→    let left = parseUnary();
   502→    while (at(T.Star) || at(T.Slash) || at(T.Percent)) {
   503→      const op = advance().value;
   504→      left = { kind: "binary", op, left, right: parseUnary() };
   505→    }
   506→    return left;
   507→  }
   508→
   509→  function parseUnary(): Expr {
   510→    // Handle unary operators: -, !, &, *
   511→    if (at(T.Minus) || at(T.Not) || at(T.Ampersand) || at(T.Star)) {
   512→      const op = advance().value;
   513→      return { kind: "unary", op, expr: parseUnary() };
   514→    }
   515→    return parsePostfix();
   516→  }
   517→
   518→  function parsePostfix(): Expr {
   519→    let expr = parsePrimary();
   520→    while (true) {
   521→      if (match(T.LParen)) {
   522→        const args: Expr[] = [];
   523→        while (!at(T.RParen) && !at(T.EOF)) {
   524→          args.push(parseExpr());
   525→          match(T.Comma);
   526→        }
   527→        expect(T.RParen);
   528→        expr = { kind: "call", callee: expr, args };
   529→      } else if (match(T.LBracket)) {
   530→        const index = parseExpr();
   531→        expect(T.RBracket);
   532→        expr = { kind: "index", object: expr, index };
   533→      } else if (match(T.Dot)) {
   534→        const prop = expect(T.Ident, "Expected property name").value;
   535→        expr = { kind: "member", object: expr, property: prop };
   536→      } else break;
   537→    }
   538→    return expr;
   539→  }
   540→
   541→  function parsePrimary(): Expr {
   542→    const t = peek();
   543→    switch (t.type) {
   544→      case T.Number: advance(); return { kind: "number", value: Number(t.value) };
   545→      case T.String: advance(); return { kind: "string", value: t.value };
   546→      case T.Bool: advance(); return { kind: "bool", value: t.value === "true" };
   547→      case T.Null: advance(); return { kind: "null" };
   548→      case T.Ident: {
   549→        advance();
   550→        // Single-param arrow: x => expr
   551→        if (at(T.FatArrow)) {
   552→          advance();
   553→          if (at(T.LBrace)) {
   554→            expect(T.LBrace);
   555→            const body = parseBody();
   556→            expect(T.RBrace);
   557→            return { kind: "fn", name: null, params: [t.value], body };
   558→          }
   559→          const expr = parseAssign();
   560→          return { kind: "fn", name: null, params: [t.value], body: [{ kind: "return", value: expr }] };
   561→        }
   562→        return { kind: "ident", name: t.value };
   563→      }
   564→      case T.LParen: {
   565→        // Try arrow function: (params) => body
   566→        const savedPos = pos;
   567→        advance(); // (
   568→
   569→        // Check for empty parens arrow: () => ...
   570→        if (at(T.RParen)) {
   571→          const rp = pos;
   572→          advance(); // )
   573→          if (at(T.FatArrow)) {
   574→            advance(); // =>
   575→            return parseArrowBody([]);
   576→          }
   577→          // Not arrow, backtrack
   578→          pos = savedPos;
   579→          advance();
   580→          const expr = parseExpr();
   581→          expect(T.RParen);
   582→          return expr;
   583→        }
   584→
   585→        // Try parsing as ident list for arrow function
   586→        let isArrow = true;
   587→        const params: string[] = [];
   588→        const tryPos = pos;
   589→        while (!at(T.RParen) && !at(T.EOF)) {
   590→          if (!at(T.Ident)) { isArrow = false; break; }
   591→          params.push(advance().value);
   592→          if (!at(T.RParen)) {
   593→            if (!match(T.Comma)) { isArrow = false; break; }
   594→          }
   595→        }
   596→        if (isArrow && at(T.RParen)) {
   597→          advance(); // )
   598→          if (at(T.FatArrow)) {
   599→            advance(); // =>
   600→            return parseArrowBody(params);
   601→          }
   602→        }
   603→
   604→        // Not arrow, backtrack and parse as grouped expression
   605→        pos = savedPos;
   606→        advance(); // (
   607→        const expr = parseExpr();
   608→        expect(T.RParen);
   609→        return expr;
   610→      }
   611→      case T.LBracket: return parseArrayLiteral();
   612→      case T.LBrace: return parseObjectLiteral();
   613→      case T.Fn: return parseFnExpr();
   614→      case T.If: return parseIfExpr();
   615→      case T.Match: return parseMatchExpr();
   616→      default: throw new Error(`Unexpected token '${t.value}' at line ${t.line}:${t.col}`);
   617→    }
   618→  }
   619→
   620→  function parseArrowBody(params: string[]): Expr {
   621→    if (at(T.LBrace)) {
   622→      expect(T.LBrace);
   623→      const body = parseBody();
   624→      expect(T.RBrace);
   625→      return { kind: "fn", name: null, params, body };
   626→    }
   627→    const expr = parseAssign();
   628→    return { kind: "fn", name: null, params, body: [{ kind: "return", value: expr }] };
   629→  }
   630→
   631→  function parseArrayLiteral(): Expr {
   632→    advance(); // [
   633→    const elements: Expr[] = [];
   634→    while (!at(T.RBracket) && !at(T.EOF)) {
   635→      elements.push(parseExpr());
   636→      match(T.Comma);
   637→    }
   638→    expect(T.RBracket);
   639→    return { kind: "array", elements };
   640→  }
   641→
   642→  function parseObjectLiteral(): Expr {
   643→    advance(); // {
   644→    const entries: { key: string; value: Expr }[] = [];
   645→    while (!at(T.RBrace) && !at(T.EOF)) {
   646→      const key = expect(T.Ident, "Expected key").value;
   647→      expect(T.Colon);
   648→      const value = parseExpr();
   649→      entries.push({ key, value });
   650→      match(T.Comma);
   651→    }
   652→    expect(T.RBrace);
   653→    return { kind: "object", entries };
   654→  }
   655→
   656→  function parseFnExpr(): Expr {
   657→    advance(); // fn
   658→    let name: string | null = null;
   659→    if (at(T.Ident)) name = advance().value;
   660→    expect(T.LParen);
   661→    const params = parseParams();
   662→    expect(T.RParen);
   663→    expect(T.LBrace);
   664→    const body = parseBody();
   665→    expect(T.RBrace);
   666→    return { kind: "fn", name, params, body };
   667→  }
   668→
   669→  function parseParams(): string[] {
   670→    const params: string[] = [];
   671→    while (!at(T.RParen) && !at(T.EOF)) {
   672→      const paramName = expect(T.Ident, "Expected parameter name").value;
   673→      params.push(paramName);
   674→      // Skip type annotation if present: name: Type
   675→      if (match(T.Colon)) {
   676→        // Skip the type - consume tokens until we hit comma or RParen
   677→        let depth = 0;
   678→        while (!at(T.Comma) && !at(T.RParen) && !at(T.EOF)) {
   679→          const t = advance();
   680→          // Handle nested brackets if needed (for complex types)
   681→          if (t.type === T.LBracket) depth++;
   682→          if (t.type === T.RBracket) depth--;
   683→          if (depth < 0) break;
   684→        }
   685→      }
   686→      match(T.Comma);
   687→    }
   688→    return params;
   689→  }
   690→
   691→  function parseBody(): Stmt[] {
   692→    const stmts: Stmt[] = [];
   693→    while (!at(T.RBrace) && !at(T.EOF)) stmts.push(parseStmt());
   694→    return stmts;
   695→  }
   696→
   697→  return parseProgram();
   698→}
