    21→export class VM {
    22→  private stack: Value[] = [];
    23→  private globals = new Map<string, Value>();
    24→  private frames: Frame[] = [];
    25→  private tryStack: TryHandler[] = [];
    26→  private ip = 0;
    27→  private output: string[] = [];
    28→  private builtinFns: Record<string, BuiltinFn>;
    29→  // Phase 8: try/catch error handling
    30→  private lastError: Value | null = null;
    31→  private inTryCall = false;
    32→  // Phase 3.7: Safety guard & iteration tracking
    33→  // Phase 3.9: Jump Table & Offset Optimization
    34→  private jumpTable: JumpTable;
    35→  private offsetCalc: OffsetCalculator = new OffsetCalculator();
    36→  // Phase 5.9: Dynamic Memory Allocator
    37→  private memoryAllocator: MemoryAllocator = new MemoryAllocator();
    38→
    39→  private traceMode = false;
    40→  private traceLogs: string[] = [];
    41→  private loopStack: LoopContext[] = [];  // Track loop start positions + iteration counts
    42→  private loopDepth = 0;                   // Track nesting depth
    43→  private readonly MAX_SAFE_ITERATIONS = 1_000_000;  // Safety guard limit
    44→
    45→  constructor(private chunk: Chunk, initialGlobals?: Map<string, Value>) {
