    50→    for (const name of Object.keys(this.builtinFns)) {
    51→      this.globals.set(name, { tag: "builtin", name });
    52→    }
    53→    // Restore persisted globals (e.g. from REPL)
    54→    if (initialGlobals) {
    55→      for (const [k, v] of initialGlobals) {
