    58→    }
    59→  }
    60→
    61→  getGlobals(): Map<string, Value> { return new Map(this.globals); }
    62→
    63→  run(): { output: string[]; result: Value } {
    64→    while (this.ip < this.chunk.code.length) {
    65→      const op = this.chunk.code[this.ip++];
    66→      if (op === Op.Halt) {
    67→        return { output: this.output, result: this.stack.length > 0 ? this.peek() : { tag: "null" } };
    68→      }
    69→      try {
    70→        this.execOp(op);
    71→      } catch (e) {
    72→        // If error was caught by a try handler
    73→        if (e instanceof Error && e.message.startsWith("__FREELANG_ERROR_CAUGHT__")) {
    74→          // Continue from the new IP (which should point to catch handler or finally)
    75→          continue;
    76→        }
    77→        // Re-throw unhandled errors
    78→        throw e;
    79→      }
    80→    }
