    82→  }
    83→
    84→  // Public API for builtins
    85→  getGlobal(name: string): Value | undefined { return this.globals.get(name); }
    86→  setGlobal(name: string, val: Value) { this.globals.set(name, val); }
    87→  getOutput(): string[] { return this.output; }
    88→  addOutput(s: string) { this.output.push(s); }
    89→  getLastError(): Value | null { return this.lastError; }
    90→  clearLastError() { this.lastError = null; }
    91→
    92→  // Phase 5.9: Memory Allocator API for builtins
    93→  getAllocator() { return this.memoryAllocator; }
    94→
    95→  // Trace mode for PC debugging
    96→  enableTrace() { this.traceMode = true; this.traceLogs = []; }
    97→  getTraceLogs(): string[] { return this.traceLogs; }
    98→
    99→  /** Call a FreeLang fn or builtin Value from within a builtin (HOFs). */
   100→  callValue(callee: Value, args: Value[]): Value {
   101→    if (callee.tag === "builtin") {
   102→      return this.builtinFns[callee.name](args, this);
   103→    }
   104→    if (callee.tag === "fn") {
   105→      const savedIp = this.ip;
   106→      const targetFrameDepth = this.frames.length;
