   108→      // Mimic Call opcode: push callee + args, push frame
   109→      this.stack.push(callee);
   110→      for (const a of args) this.stack.push(a);
   111→      this.frames.push({
   112→        retAddr: savedIp,
   113→        baseSlot: this.stack.length - args.length,
   114→        fn: callee.name,
   115→        upvalues: callee.freeVars,
   116→      });
