   118→
   119→      // Execute until our frame is popped by Return
   120→      try {
   121→        while (this.frames.length > targetFrameDepth) {
   122→          const op = this.chunk.code[this.ip++];
   123→          this.execOp(op);
   124→        }
   125→      } catch (e) {
   126→        // Re-throw sentinel errors so try_call can catch them
   127→        if (e instanceof Error && e.message === "__FREELANG_ERROR_CAUGHT__") {
   128→          throw e;
   129→        }
   130→        // Re-throw other errors
   131→        throw e;
   132→      }
