   134→      return this.stack.pop()!;
   135→    }
   136→    throw new Error(`Cannot call ${callee.tag}`);
   137→  }
   138→
   139→  /** Safe call for try_call builtin - captures errors as Value objects */
   140→  trySafeCall(callee: Value, args: Value[]): { ok: boolean; value?: Value; error?: Value } {
   141→    this.clearLastError();
   142→    this.inTryCall = true;
   143→
   144→    try {
   145→      if (callee.tag === "builtin") {
   146→        const retVal = this.builtinFns[callee.name](args, this);
   147→        return { ok: true, value: retVal };
   148→      }
   149→      if (callee.tag === "fn") {
   150→        const retVal = this.callValue(callee, args);
   151→        return { ok: true, value: retVal };
   152→      }
   153→      return { ok: false, error: { tag: "str", val: `Cannot call ${callee.tag}` } };
   154→    } catch (e) {
   155→      // Check if a FreeLang error occurred
   156→      if (e instanceof Error && e.message.startsWith("__FREELANG_ERROR_CAUGHT__")) {
   157→        // Return the last error that was caught
   158→        return { ok: false, error: this.lastError || { tag: "str", val: "Unknown error" } };
   159→      }
   160→      // Otherwise return string error
   161→      return { ok: false, error: { tag: "str", val: String(e) } };
   162→    } finally {
   163→      this.inTryCall = false;
   164→    }
   165→  }
   166→
   167→  stringify(v: Value): string {
   168→    switch (v.tag) {
   169→      case "num": return String(v.val);
   170→      case "str": return v.val;
   171→      case "bool": return String(v.val);
   172→      case "null": return "null";
   173→      case "array": return "[" + v.val.map(e => this.stringify(e)).join(", ") + "]";
   174→      case "object": {
   175→        const entries = Array.from(v.val.entries()).map(([k, v2]) => `${k}: ${this.stringify(v2)}`);
