   193→      case Op.Add: { const b = this.pop(), a = this.pop(); this.stack.push(this.add(a, b)); break; }
   194→      case Op.Sub: { const b = this.popNum(), a = this.popNum(); this.stack.push(num(a - b)); break; }
   195→      case Op.Mul: { const b = this.popNum(), a = this.popNum(); this.stack.push(num(a * b)); break; }
   196→      case Op.Div: { const b = this.popNum(), a = this.popNum(); if (b === 0) this.runtimeError("Division by zero"); this.stack.push(num(a / b)); break; }
