   203→      case Op.Lt: { const b = this.popNum(), a = this.popNum(); this.stack.push(bool(a < b)); break; }
   204→      case Op.Gt: { const b = this.popNum(), a = this.popNum(); this.stack.push(bool(a > b)); break; }
   205→      case Op.Lte: { const b = this.popNum(), a = this.popNum(); this.stack.push(bool(a <= b)); break; }
   206→      case Op.Gte: { const b = this.popNum(), a = this.popNum(); this.stack.push(bool(a >= b)); break; }
