   374→      }
   375→
   376→      // Array
   377→      case Op.NewArray: {
   378→        const len = this.chunk.code[this.ip++];
   379→        const elements = this.stack.splice(this.stack.length - len, len);
   380→        this.stack.push({ tag: "array", val: elements });
   381→        break;
   382→      }
   383→      case Op.Index: {
   384→        const idx = this.pop();
   385→        const obj = this.pop();
   386→        if (obj.tag === "array" && idx.tag === "num") {
   387→          this.stack.push(obj.val[Math.floor(idx.val)] ?? { tag: "null" });
   388→        } else if (obj.tag === "object" && idx.tag === "str") {
   389→          this.stack.push(obj.val.get(idx.val) ?? { tag: "null" });
   390→        } else if (obj.tag === "str" && idx.tag === "num") {
   391→          const ch = obj.val[Math.floor(idx.val)];
   392→          this.stack.push(ch ? { tag: "str", val: ch } : { tag: "null" });
   393→        } else {
   394→          this.stack.push({ tag: "null" });
   395→        }
   396→        break;
   397→      }
   398→      case Op.SetIndex: {
   399→        const idx = this.pop();
   400→        const obj = this.pop();
   401→        const val = this.pop();
   402→        if (obj.tag === "array" && idx.tag === "num") obj.val[Math.floor(idx.val)] = val;
   403→        else if (obj.tag === "object" && idx.tag === "str") obj.val.set(idx.val, val);
