   405→        break;
   406→      }
   407→
   408→      // Object
   409→      case Op.NewObject: {
   410→        const count = this.chunk.code[this.ip++];
   411→        const map = new Map<string, Value>();
   412→        const items = this.stack.splice(this.stack.length - count * 2, count * 2);
   413→        for (let i = 0; i < items.length; i += 2) {
   414→          map.set((items[i] as { tag: "str"; val: string }).val, items[i + 1]);
   415→        }
   416→        this.stack.push({ tag: "object", val: map });
   417→        break;
   418→      }
   419→      case Op.GetProp: {
   420→        const name = this.chunk.constants[this.chunk.code[this.ip++]] as { tag: "str"; val: string };
