   451→      }
   452→      case Op.StoreFree: {
   453→        const idx = this.chunk.code[this.ip++];
   454→        const frame = this.frames[this.frames.length - 1];
   455→        frame.upvalues[idx] = this.peek();
   456→        break;
   457→      }
   458→
   459→      // Print
   460→      case Op.Print: this.output.push(this.stringify(this.pop())); break;
   461→      case Op.Println: this.output.push(this.stringify(this.pop()) + "\n"); break;
   462→
   463→      // Try/Catch
   464→      case Op.TryBegin: {
   465→        const catchAddr = this.chunk.code[this.ip++];
   466→        this.tryStack.push({ catchAddr, stackDepth: this.stack.length, frameDepth: this.frames.length });
   467→        break;
   468→      }
   469→      case Op.TryEnd: this.tryStack.pop(); break;
   470→      case Op.Throw: {
   471→        const err = this.pop();
   472→        this.handleError(err);
   473→        break;
   474→      }
   475→
   476→      // Iterator
   477→      case Op.Iter: {
   478→        const val = this.pop();
   479→        if (val.tag === "array") this.stack.push({ tag: "iter", val: val.val, idx: 0 });
   480→        else if (val.tag === "str") this.stack.push({ tag: "iter", val: val.val.split("").map(c => ({ tag: "str", val: c } as Value)), idx: 0 });
   481→        else this.runtimeError("Cannot iterate over " + val.tag);
   482→        break;
   483→      }
   484→      case Op.IterNext: {
   485→        const iter = this.pop();
   486→        if (iter.tag === "iter") {
   487→          this.stack.push(iter.val[iter.idx] ?? { tag: "null" });
   488→          iter.idx++;
   489→        } else {
   490→          this.stack.push({ tag: "null" });
   491→        }
   492→        break;
   493→      }
   494→      case Op.IterDone: {
   495→        const iter = this.pop();
   496→        this.stack.push(bool(iter.tag === "iter" && iter.idx >= iter.val.length));
   497→        break;
   498→      }
   499→
   500→      // v5.9.1: Pointer operators
   501→      case Op.AddrOf: {
   502→        const val = this.pop();
   503→        // Address-of: create a pointer to the value with its address
   504→        // For simplicity, we use a numeric ID as the address
   505→        const ptrAddr = this.memoryAllocator.allocate(JSON.stringify(val).length);
   506→        if (ptrAddr > 0) {
   507→          this.stack.push({ tag: "ptr", addr: ptrAddr, target: val });
   508→        } else {
   509→          this.runtimeError("Cannot allocate memory for pointer");
   510→        }
   511→        break;
   512→      }
   513→      case Op.Deref: {
   514→        const ptr = this.pop();
   515→        if (ptr.tag === "ptr") {
   516→          // Dereference: extract the target value from the pointer
   517→          this.stack.push(ptr.target);
   518→        } else {
   519→          this.runtimeError(`Cannot dereference non-pointer type ${ptr.tag}`);
   520→        }
   521→        break;
   522→      }
   523→
   524→      default: this.runtimeError(`Unknown opcode ${op}`);
   525→    }
   526→  }
   527→
   528→  private peek(): Value { return this.stack[this.stack.length - 1]; }
   529→  private pop(): Value { return this.stack.pop()!; }
   530→  private baseSlot(): number { return this.frames.length > 0 ? this.frames[this.frames.length - 1].baseSlot : 0; }
   531→
   532→  // Phase 3.8: Memory snapshot for state integrity
   533→  private captureSnapshot(): { stackHeight: number; globals: Map<string, Value>; locals: Value[] } {
   534→    const stackHeight = this.stack.length;
   535→    const globals = new Map(this.globals);
   536→    const locals = this.stack.slice(0, this.baseSlot()).map(v => ({ ...v })); // shallow copy
   537→    return { stackHeight, globals, locals };
   538→  }
   539→
   540→  private compareSnapshots(
   541→    before: { stackHeight: number; globals: Map<string, Value>; locals: Value[] },
   542→    after: { stackHeight: number; globals: Map<string, Value>; locals: Value[] }
   543→  ): { stackBalanced: boolean; globalChanges: [string, Value, Value][]; localChanges: boolean } {
   544→    const stackBalanced = before.stackHeight === after.stackHeight;
   545→
   546→    // Find global changes
   547→    const globalChanges: [string, Value, Value][] = [];
   548→    for (const [key, beforeVal] of before.globals) {
   549→      const afterVal = after.globals.get(key);
   550→      if (!this.valEq(beforeVal, afterVal || { tag: "null" })) {
   551→        globalChanges.push([key, beforeVal, afterVal || { tag: "null" }]);
   552→      }
   553→    }
   554→    for (const [key] of after.globals) {
   555→      if (!before.globals.has(key)) {
   556→        globalChanges.push([key, { tag: "null" }, after.globals.get(key)!]);
   557→      }
   558→    }
   559→
   560→    // Check if locals changed (shouldn't in safe code)
   561→    const localChanges = before.locals.length !== after.locals.length ||
   562→      before.locals.some((v, i) => !this.valEq(v, after.locals[i] || { tag: "null" }));
   563→
   564→    return { stackBalanced, globalChanges, localChanges };
   565→  }
   566→
   567→  private popNum(): number {
   568→    const v = this.pop();
   569→    if (v.tag !== "num") this.runtimeError(`Expected number, got ${v.tag}`);
   570→    return (v as any).val;
   571→  }
   572→
   573→  private add(a: Value, b: Value): Value {
   574→    if (a.tag === "num" && b.tag === "num") return num(a.val + b.val);
   575→    if (a.tag === "str" || b.tag === "str") return { tag: "str", val: this.stringify(a) + this.stringify(b) };
   576→    if (a.tag === "array" && b.tag === "array") return { tag: "array", val: [...a.val, ...b.val] };
   577→    return num(0);
   578→  }
   579→
   580→  private valEq(a: Value, b: Value): boolean {
   581→    if (a.tag !== b.tag) return false;
   582→    if (a.tag === "null") return true;
   583→    if (a.tag === "num" || a.tag === "str" || a.tag === "bool") return (a as any).val === (b as any).val;
   584→    return a === b;
   585→  }
   586→
   587→  private truthy(v: Value): boolean {
   588→    if (v.tag === "null") return false;
   589→    if (v.tag === "bool") return v.val;
   590→    if (v.tag === "num") return v.val !== 0;
   591→    if (v.tag === "str") return v.val !== "";
   592→    if (v.tag === "array") return v.val.length > 0;
   593→    return true;
   594→  }
   595→
   596→  private handleError(err: Value) {
   597→    this.lastError = err;
   598→    if (this.tryStack.length > 0) {
   599→      const handler = this.tryStack.pop()!;
   600→      this.stack.length = handler.stackDepth;
   601→      this.frames.length = handler.frameDepth;
   602→      this.stack.push(err);
   603→      this.ip = handler.catchAddr;
   604→    } else {
   605→      // Throw error which will be caught by caller (trySafeCall, run, etc)
   606→      throw new Error(`__FREELANG_ERROR_CAUGHT__:${this.stringify(err)}`);
   607→    }
   608→  }
   609→
   610→  private runtimeError(msg: string): never {
   611→    const err: Value = { tag: "str", val: msg };
   612→    if (this.tryStack.length > 0) {
   613→      this.handleError(err);
   614→      // Throw sentinel that run() loop will catch and handle
   615→      throw new Error("__FREELANG_ERROR_CAUGHT__");
   616→    }
   617→    throw new Error(`Runtime Error: ${msg}`);
   618→  }
   619→}
   620→
   621→function num(n: number): Value { return { tag: "num", val: n }; }
   622→function bool(b: boolean): Value { return { tag: "bool", val: b }; }
